import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { trackEvent } from "../analytics.js";
import { writeClipboardText } from "../clipboard.js";
import { useT } from "../i18n.js";
import { extractShareErrorMessage, optimisticallyUpdateShareCache, rollbackShareCache, useShareMutationGuard, useShareMutations, useShareOrgMemberSearch, useShareQuery, } from "./share-controller-helpers.js";
export function useShareDialogController({ open, onClose, resourceType, resourceId, resourceTitle, shareUrl, embedUrl, }) {
    const t = useT();
    const { query: sharesQuery, queryKey: shareQueryKey, queryClient, } = useShareQuery(resourceType, resourceId);
    const { share: shareMutation, unshare: unshareMutation, setVisibility: visibilityMutation, } = useShareMutations();
    const memberSearch = useShareOrgMemberSearch("", true, {
        limit: undefined,
        debounceMs: 0,
    });
    const orgMembers = memberSearch.members;
    const hasLinkTab = Boolean(shareUrl);
    const hasEmbedTab = Boolean(embedUrl);
    const tabsEnabled = hasLinkTab || hasEmbedTab;
    const [activeTab, setActiveTab] = useState(hasLinkTab ? "link" : "invite");
    const [email, setEmail] = useState("");
    const [role, setRole] = useState("viewer");
    const [notifyPeople, setNotifyPeople] = useState(true);
    const [message, setMessage] = useState("");
    const [messageOpen, setMessageOpen] = useState(false);
    const [copiedField, setCopiedField] = useState(null);
    const [visibilityOverride, setVisibilityOverride] = useState(null);
    const [mutationError, setMutationError] = useState(null);
    const visibilityGuard = useShareMutationGuard();
    const copyResetTimer = useRef(null);
    useEffect(() => {
        if (open)
            setActiveTab(hasLinkTab ? "link" : "invite");
    }, [hasLinkTab, open]);
    useEffect(() => () => {
        if (copyResetTimer.current)
            clearTimeout(copyResetTimer.current);
    }, []);
    const data = sharesQuery.data;
    const visibility = visibilityOverride ?? data?.visibility ?? "private";
    const canManage = data?.role === "owner" || data?.role === "admin";
    const visibilityOptions = useMemo(() => ["private", "org", "public"]
        .filter((value) => value !== "public" ||
        value === visibility ||
        data?.policy?.allowPublic !== false)
        .map((value) => visibilityOption(value, t)), [data?.policy?.allowPublic, t, visibility]);
    const roleOptions = useMemo(() => ["viewer", "commenter", "editor", "admin"].map((value) => roleOption(value, t)), [t]);
    const refetch = useCallback(() => sharesQuery.refetch(), [sharesQuery]);
    const setVisibility = useCallback((next) => {
        if (!canManage || next === visibility)
            return;
        const requestId = visibilityGuard.begin();
        const previous = optimisticallyUpdateShareCache(queryClient, shareQueryKey, (cached) => (cached ? { ...cached, visibility: next } : cached));
        setMutationError(null);
        setVisibilityOverride(next);
        visibilityMutation.mutate({ resourceType, resourceId, visibility: next }, {
            onSuccess: (result) => {
                if (visibilityGuard.isLatest(requestId)) {
                    const resultVisibility = typeof result === "object" &&
                        result !== null &&
                        "visibility" in result &&
                        result.visibility;
                    optimisticallyUpdateShareCache(queryClient, shareQueryKey, (cached) => cached
                        ? {
                            ...cached,
                            visibility: resultVisibility ??
                                next,
                        }
                        : cached);
                }
                if (!visibilityGuard.isLatest(requestId))
                    return;
                Promise.resolve(refetch())
                    .catch((error) => {
                    if (visibilityGuard.isLatest(requestId)) {
                        setMutationError(extractShareErrorMessage(error));
                    }
                })
                    .finally(() => {
                    if (visibilityGuard.isLatest(requestId)) {
                        setVisibilityOverride(null);
                    }
                });
            },
            onError: (error) => {
                if (visibilityGuard.isLatest(requestId)) {
                    rollbackShareCache(queryClient, shareQueryKey, previous);
                    setVisibilityOverride(null);
                    setMutationError(extractShareErrorMessage(error));
                }
            },
        });
    }, [
        canManage,
        refetch,
        resourceId,
        resourceType,
        queryClient,
        shareQueryKey,
        visibility,
        visibilityGuard,
        visibilityMutation,
    ]);
    const submitInvite = useCallback(() => {
        const principalId = email.trim();
        if (!canManage || !principalId)
            return;
        const notificationMessage = notifyPeople ? message.trim() : "";
        const optimistic = {
            id: `pending-${principalId}`,
            principalType: "user",
            principalId,
            role,
        };
        const previous = optimisticallyUpdateShareCache(queryClient, shareQueryKey, (cached) => cached ? { ...cached, shares: [...cached.shares, optimistic] } : cached);
        setMutationError(null);
        shareMutation.mutate({
            resourceType,
            resourceId,
            principalType: "user",
            principalId,
            role,
            notify: notifyPeople,
            resourceUrl: getNotificationUrl(shareUrl),
            ...(notificationMessage ? { message: notificationMessage } : {}),
        }, {
            onSuccess: () => {
                setEmail("");
                setMessage("");
                setMessageOpen(false);
                void refetch();
            },
            onError: (error) => {
                rollbackShareCache(queryClient, shareQueryKey, previous);
                setMutationError(extractShareErrorMessage(error));
            },
        });
    }, [
        canManage,
        email,
        message,
        notifyPeople,
        refetch,
        resourceId,
        resourceType,
        role,
        queryClient,
        shareQueryKey,
        shareMutation,
        shareUrl,
    ]);
    const removeShare = useCallback((share) => {
        if (!canManage)
            return;
        const previous = optimisticallyUpdateShareCache(queryClient, shareQueryKey, (cached) => cached
            ? {
                ...cached,
                shares: cached.shares.filter((current) => !(current.principalType === share.principalType &&
                    current.principalId === share.principalId)),
            }
            : cached);
        setMutationError(null);
        unshareMutation.mutate({
            resourceType,
            resourceId,
            principalType: share.principalType,
            principalId: share.principalId,
        }, {
            onSuccess: refetch,
            onError: (error) => {
                rollbackShareCache(queryClient, shareQueryKey, previous);
                setMutationError(extractShareErrorMessage(error));
            },
        });
    }, [
        canManage,
        queryClient,
        refetch,
        resourceId,
        resourceType,
        shareQueryKey,
        unshareMutation,
    ]);
    const copy = useCallback(async (field, value) => {
        const copied = await writeClipboardText(value);
        if (!copied) {
            setCopiedField(null);
            return false;
        }
        setCopiedField(field);
        trackEvent("share_link_copied", {
            resource_type: resourceType,
            resource_id: resourceId,
            link_type: field,
        });
        if (copyResetTimer.current)
            clearTimeout(copyResetTimer.current);
        copyResetTimer.current = setTimeout(() => setCopiedField(null), 1_400);
        return true;
    }, [resourceId, resourceType]);
    const currentVisibility = visibilityOption(visibility, t);
    const people = buildPeople(data, orgMembers, t);
    return {
        open,
        onOpenChange: (nextOpen) => {
            if (!nextOpen)
                onClose();
        },
        close: onClose,
        title: resourceTitle
            ? t("share.titleWithResource", { title: resourceTitle })
            : t("share.titleWithType", { type: resourceType }),
        ownerLabel: data?.ownerEmail
            ? t("share.owner", {
                name: displayName(data.ownerEmail, orgMembers),
            })
            : null,
        activeTab,
        setActiveTab,
        tabsEnabled,
        tabs: [
            ...(hasLinkTab
                ? [{ value: "link", label: t("share.link") }]
                : []),
            ...(hasEmbedTab
                ? [{ value: "embed", label: t("share.embed") }]
                : []),
        ],
        labels: {
            close: t("share.close"),
            shareOptions: t("share.shareOptions"),
            generalAccess: t("share.generalAccess"),
            shareLink: t("share.shareLink"),
            peopleWithAccess: t("share.peopleWithAccess"),
            addPeopleByEmail: t("share.addPeopleByEmail"),
            notifyPeople: t("share.notifyPeople"),
            addMessage: t("share.addMessage"),
            hideMessage: t("share.hideMessage"),
            messagePlaceholder: t("share.messagePlaceholder"),
            role: t("share.role"),
            remove: t("share.remove"),
            noAccess: t("share.noAccess"),
            copy: t("share.copy"),
            copied: t("share.copied"),
            embedUrl: t("share.embedUrl"),
            embedCode: t("share.embedCode"),
        },
        visibility: {
            value: visibility,
            label: currentVisibility.label,
            description: currentVisibility.description,
            options: visibilityOptions,
            disabled: !canManage,
            pending: visibilityMutation.isPending,
            set: setVisibility,
        },
        invite: {
            email,
            setEmail,
            role,
            setRole,
            roleOptions,
            notifyPeople,
            setNotifyPeople,
            showNotifyPeople: email.trim().length > 0,
            message,
            setMessage,
            messageOpen,
            setMessageOpen,
            disabled: !canManage || email.trim().length === 0,
            pending: shareMutation.isPending,
            submit: submitInvite,
        },
        people,
        removeShare,
        removing: unshareMutation.isPending,
        shareUrl,
        embedUrl,
        embedCode: embedUrl ? createEmbedCode(embedUrl) : undefined,
        copiedField,
        copy,
        loading: sharesQuery.isLoading,
        error: sharesQuery.error ?? mutationError,
        refetch,
        canManage,
        agentReadable: data?.agentReadable === true,
    };
}
function visibilityOption(visibility, t) {
    const keys = {
        private: ["share.private", "share.privateDescription"],
        org: ["share.organization", "share.organizationDescription"],
        public: ["share.public", "share.publicDescription"],
    };
    return {
        value: visibility,
        label: t(keys[visibility][0]),
        description: t(keys[visibility][1]),
    };
}
function roleOption(role, t) {
    const keys = {
        viewer: ["share.viewer", "share.viewerDescription"],
        commenter: ["share.commenter", "share.commenterDescription"],
        editor: ["share.editor", "share.editorDescription"],
        admin: ["share.admin", "share.adminDescription"],
    };
    return {
        value: role,
        label: t(keys[role][0]),
        description: t(keys[role][1]),
    };
}
function buildPeople(data, members, t) {
    const people = [];
    if (data?.ownerEmail) {
        const label = displayName(data.ownerEmail, members);
        people.push({
            key: `owner:${data.ownerEmail}`,
            label,
            roleLabel: t("share.ownerRole"),
            principalType: "owner",
            avatarText: avatarText(label),
            share: null,
        });
    }
    for (const share of data?.shares ?? []) {
        const label = principalLabel(share, members);
        people.push({
            key: `${share.principalType}:${share.principalId}`,
            label,
            roleLabel: capitalize(share.role),
            principalType: share.principalType,
            avatarText: share.principalType === "org" ? null : avatarText(label),
            share,
        });
    }
    return people;
}
function displayName(email, members) {
    const normalized = email.trim().toLowerCase();
    const match = members.find((member) => member.email.toLowerCase() === normalized);
    if (match?.name?.trim())
        return match.name;
    return normalized.includes("@") ? email : "Unknown person";
}
function principalLabel(share, members) {
    const serverLabel = share.displayName?.trim();
    if (serverLabel)
        return serverLabel;
    if (share.principalType === "org")
        return "Organization";
    return displayName(share.principalId, members);
}
function avatarText(label) {
    return (label.split("@")[0]?.[0] ?? label[0] ?? "?").toUpperCase();
}
function capitalize(value) {
    return value.charAt(0).toUpperCase() + value.slice(1);
}
function getNotificationUrl(explicit) {
    if (explicit)
        return explicit;
    if (typeof window === "undefined")
        return undefined;
    return window.location.href;
}
function createEmbedCode(embedUrl) {
    return `<div style="position:relative;padding-bottom:56.25%;height:0"><iframe src="${embedUrl}" frameborder="0" allowfullscreen allow="autoplay; picture-in-picture" style="position:absolute;inset:0;width:100%;height:100%"></iframe></div>`;
}
